#include <bits/stdc++.h>
using namespace std;const int N=200005,K=100005,Z=3000005;int a[N],p[N],h[N],to[N],nx[N],f[N][10],fc[N],o[N][10],q[K],u[K],v[K],g[K][10],gc[K],c[Z],la[Z],an[N],de[N],sn[N*2],ss[N*2],pr[5000],sv[46350],pc;void F(int x,int*y,int&k){k=0;for(int j=0;j<pc&&1LL*pr[j]*pr[j]<=x;j++)if(x%pr[j]==0){y[k++]=pr[j];while(x%pr[j]==0)x/=pr[j];}if(x>1)y[k++]=x;}void B(int n,int r){int z=0;sn[z]=r;ss[z++]=1;while(z){int x=sn[--z],s=ss[z];if(s>0){de[x]=p[x]?de[p[x]]+1:1;an[x]=-1;for(int i=0;i<fc[x];i++){int y=la[f[x][i]];o[x][i]=y;if(y&&(!~an[x]||de[y]>de[an[x]]))an[x]=y;la[f[x][i]]=x;}sn[z]=x;ss[z++]=-1;for(int y=h[x];y;y=nx[y])sn[z]=to[y],ss[z++]=1;}else for(int i=0;i<fc[x];i++)la[f[x][i]]=o[x][i];}}int main(){ios::sync_with_stdio(0);cin.tie(0);int n,k,z=0,e=0,r=0;for(int i=2;i<=46340;i++)if(!sv[i]){pr[pc++]=i;if(1LL*i*i<=46340)for(int j=i*i;j<=46340;j+=i)sv[j]=1;}cin>>n>>k;for(int i=1;i<=n;i++){cin>>a[i];F(a[i],f[i],fc[i]);for(int j=0;j<fc[i];j++)c[z++]=f[i][j];}for(int i=1,x,y;i<n;i++){cin>>x>>y;p[y]=x;to[++e]=y;nx[e]=h[x];h[x]=e;}for(int i=1;i<=n;i++)if(!p[i])r=i;for(int i=0;i<k;i++){cin>>q[i]>>u[i];if(q[i]==2){cin>>v[i];F(v[i],g[i],gc[i]);for(int j=0;j<gc[i];j++)c[z++]=g[i][j];}}sort(c,c+z);z=unique(c,c+z)-c;for(int i=1;i<=n;i++)for(int j=0;j<fc[i];j++)f[i][j]=lower_bound(c,c+z,f[i][j])-c+1;for(int i=0;i<k;i++)for(int j=0;j<gc[i];j++)g[i][j]=lower_bound(c,c+z,g[i][j])-c+1;B(n,r);for(int i=0;i<k;i++)if(q[i]==1)cout<<an[u[i]]<<'\n';else{a[u[i]]=v[i];fc[u[i]]=gc[i];for(int j=0;j<gc[i];j++)f[u[i]][j]=g[i][j];B(n,r);}}
